/* Token Radar's night theme. One palette, two radii, two families; the rest is spacing and hairlines. */
:root {
  --canvas: #0d1311;
  --panel: #141c19;
  --panel-2: #1a2420;
  --ink: #e8efe9;
  --muted: #8ea399;
  --faint: #5f7268;
  --border: #26332c;
  --accent: #e2a63d;
  --accent-ink: #181103;
  --pos: #45b781;
  --neg: #d9604e;
  --radius-ctl: 8px;
  --radius-panel: 14px;
  --font-body: system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-num: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --s1: 4px;
  --s2: 8px;
  --s3: 12px;
  --s4: 16px;
  --s5: 24px;
  --s6: 32px;
  --s7: 48px;
}

* { box-sizing: border-box; }
html { color-scheme: dark; }
body {
  margin: 0;
  background: var(--canvas);
  color: var(--ink);
  font: 400 15px/1.5 var(--font-body);
  text-wrap: pretty;
}
h1, h2, h3 { margin: 0; letter-spacing: -0.02em; text-wrap: balance; }
h1 { font-size: 30px; line-height: 1.15; font-weight: 650; }
h2 { font-size: 20px; line-height: 1.2; font-weight: 600; }
h3 { font-size: 15px; line-height: 1.25; font-weight: 600; }
p { margin: 0; }
button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }
a { color: var(--accent); }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.skip {
  position: absolute; left: -9999px; top: 0; padding: var(--s2) var(--s4);
  background: var(--panel); border: 1px solid var(--border); z-index: 20;
}
.skip:focus { left: var(--s4); top: var(--s4); }

.shell { max-width: 1320px; margin: 0 auto; padding: var(--s5) var(--s6) var(--s7); }

/* header */
.top {
  display: flex; align-items: flex-start; justify-content: space-between; gap: var(--s5);
  padding-bottom: var(--s4); border-bottom: 1px solid var(--border);
}
.brand { display: flex; align-items: center; gap: var(--s3); }
.mark { width: 10px; height: 10px; border-radius: 50%; background: var(--accent); box-shadow: 0 0 0 4px color-mix(in srgb, var(--accent) 18%, transparent); flex: none; }
.brand-name { font-family: var(--font-num); font-size: 13px; letter-spacing: 0.14em; text-transform: uppercase; color: var(--muted); }
.top-meta { display: flex; flex-wrap: wrap; gap: var(--s3); justify-content: flex-end; color: var(--faint); font-size: 13px; }
.top-meta span { white-space: nowrap; }

/* hero */
.lede { display: grid; grid-template-columns: minmax(0, 1.35fr) minmax(280px, 0.65fr); gap: var(--s6); padding: var(--s6) 0 var(--s5); }
.lede p { color: var(--muted); max-width: 64ch; margin-top: var(--s2); }
.facts { display: grid; gap: var(--s2); align-content: start; border-left: 1px solid var(--border); padding-left: var(--s5); }
.fact { display: flex; align-items: baseline; justify-content: space-between; gap: var(--s3); }
.fact b { font-family: var(--font-num); font-size: 15px; font-weight: 500; }
.fact span { color: var(--muted); font-size: 13px; }

/* kpis + podium */
.kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--s3); padding-bottom: var(--s5); }
.kpi { background: var(--panel); border: 1px solid var(--border); border-radius: var(--radius-panel); padding: var(--s4); }
.kpi .k { color: var(--faint); font-size: 12px; letter-spacing: 0.04em; text-transform: uppercase; }
.kpi .v { font-family: var(--font-num); font-size: 24px; font-weight: 600; margin-top: var(--s1); }
.kpi .d { color: var(--muted); font-size: 12px; margin-top: var(--s1); }
.podium { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--s3); padding-bottom: var(--s5); }
.pod { background: var(--panel); border: 1px solid var(--border); border-radius: var(--radius-panel); padding: var(--s4) var(--s5); position: relative; }
.pod .rk { font-family: var(--font-num); font-size: 12px; color: var(--accent); letter-spacing: 0.1em; }
.pod h3 { margin-top: var(--s1); font-size: 17px; }
.pod .sub { color: var(--muted); font-size: 12px; margin-top: var(--s1); }
.pod .val { font-family: var(--font-num); font-size: 30px; font-weight: 600; margin-top: var(--s3); }
.pod .val span { font-size: 12px; color: var(--muted); font-weight: 400; }
.pod .tvl { color: var(--faint); font-size: 12px; font-family: var(--font-num); margin-top: var(--s1); }
.pod.first { border-color: color-mix(in srgb, var(--accent) 45%, var(--border)); }

/* controls */
.controls { display: flex; flex-wrap: wrap; align-items: end; gap: var(--s3); padding: var(--s4) 0; border-top: 1px solid var(--border); }
.field { display: grid; gap: var(--s1); }
.field label { color: var(--faint); font-size: 12px; }
.field input, .field select {
  min-height: 36px; padding: 0 var(--s3); border: 1px solid var(--border); border-radius: var(--radius-ctl);
  background: var(--panel); color: var(--ink); min-width: 180px;
}
.field input { min-width: 320px; }
.field input::placeholder { color: var(--faint); }
.tabs { display: flex; gap: var(--s1); padding: 3px; border: 1px solid var(--border); border-radius: var(--radius-ctl); background: var(--panel); }
.tabs button { min-height: 30px; padding: 0 var(--s3); border: 0; border-radius: 6px; background: transparent; color: var(--muted); }
.tabs button[aria-pressed="true"] { background: var(--accent); color: var(--accent-ink); font-weight: 600; }
.count { margin-left: auto; color: var(--faint); font-size: 13px; align-self: center; }

/* tables */
.panel { background: var(--panel); border: 1px solid var(--border); border-radius: var(--radius-panel); overflow: hidden; }
.table-wrap { overflow-x: auto; }
table { width: 100%; border-collapse: collapse; font-size: 14px; }
caption { text-align: left; padding: var(--s4) var(--s4) 0; color: var(--muted); font-size: 13px; }
th, td { padding: var(--s3); border-bottom: 1px solid var(--border); text-align: left; vertical-align: middle; }
th { color: var(--faint); font-size: 12px; font-weight: 500; white-space: nowrap; }
th button { display: inline-flex; align-items: center; gap: var(--s1); border: 0; background: none; padding: 0; color: inherit; font: inherit; letter-spacing: inherit; text-transform: inherit; }
th button:hover { color: var(--ink); }
tbody tr { cursor: pointer; }
tbody tr:hover { background: var(--panel-2); }
tbody tr[data-selected="true"] { background: color-mix(in srgb, var(--accent) 12%, var(--panel)); }
.num { font-family: var(--font-num); font-variant-numeric: tabular-nums; white-space: nowrap; }
.name { display: grid; gap: 2px; }
.name b { font-weight: 600; }
.sub { color: var(--muted); font-size: 12px; }
.pos { color: var(--pos); }
.neg { color: var(--neg); }
.bar { width: 120px; height: 6px; border-radius: 3px; background: var(--border); overflow: hidden; }
.bar i { display: block; height: 100%; background: var(--accent); }
.implied { display: flex; align-items: center; gap: var(--s2); }
.status { display: inline-flex; align-items: center; gap: 6px; color: var(--muted); font-size: 12px; white-space: nowrap; }
.status::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--pos); }
td.rankcell { color: var(--faint); }
tr.top3 td.rankcell { color: var(--accent); font-weight: 700; }

/* model panel + footer */
.model { margin-top: var(--s4); padding: var(--s5); display: grid; gap: var(--s3); }
.formula { font-family: var(--font-num); font-size: 13px; line-height: 1.8; color: var(--muted); overflow-wrap: anywhere; }
.model .cols { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: var(--s3); }
.mnote { color: var(--faint); font-size: 13px; }
.foot { margin-top: var(--s5); padding-top: var(--s4); border-top: 1px solid var(--border); color: var(--faint); font-size: 12px; display: flex; flex-wrap: wrap; gap: var(--s3); justify-content: space-between; }

.empty { padding: var(--s7) var(--s5); text-align: center; display: grid; gap: var(--s3); justify-items: center; }
.empty p { color: var(--muted); }
.button { min-height: 36px; padding: 0 var(--s4); border: 1px solid var(--border); border-radius: var(--radius-ctl); background: var(--panel-2); }
.button.primary { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); font-weight: 600; }

/* detail dialog */
.detail {
  position: fixed; inset: 24px 24px 24px auto; width: min(560px, calc(92vw - 24px)); z-index: 10;
  background: var(--panel); border: 1px solid var(--border); border-radius: var(--radius-panel);
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.45); padding: var(--s5); overflow-y: auto; margin: 0;
}
.detail[hidden] { display: none; }
.detail::backdrop { background: rgba(6, 10, 8, 0.55); }
.detail-head { display: flex; align-items: start; justify-content: space-between; gap: var(--s4); }
.detail-head > div { min-width: 0; }
.detail-head .sub { overflow-wrap: anywhere; }
.close { flex: none; min-width: 32px; min-height: 32px; padding: 0 var(--s2); white-space: nowrap; border: 1px solid var(--border); border-radius: var(--radius-ctl); background: var(--panel-2); }
.detail h2 { margin-top: var(--s1); }
.detail .sub { margin-top: var(--s1); }
.detail-section { margin-top: var(--s5); padding-top: var(--s4); border-top: 1px solid var(--border); }
.detail-section h3 { margin-bottom: var(--s2); }
.equation { display: grid; gap: var(--s2); font-family: var(--font-num); font-size: 13px; }
.equation div { display: flex; justify-content: space-between; gap: var(--s3); }
.equation span { color: var(--muted); }
.equation .total { font-size: 16px; color: var(--accent); font-weight: 700; }
.steps { margin: 0; padding-left: var(--s5); display: grid; gap: var(--s3); }
.steps li { padding-left: var(--s1); }
.steps b { display: block; font-weight: 500; }
.cost { color: var(--muted); font-size: 12px; font-family: var(--font-num); display: block; margin-top: 2px; }
.chip { display: inline-block; padding: 1px var(--s2); border: 1px solid var(--border); border-radius: 999px; color: var(--muted); font-size: 12px; font-family: var(--font-num); }

@media (max-width: 980px) {
  .shell { padding: var(--s4); }
  .lede { grid-template-columns: 1fr; gap: var(--s4); }
  .facts { border-left: 0; border-top: 1px solid var(--border); padding-left: 0; padding-top: var(--s4); }
  .kpis { grid-template-columns: repeat(2, 1fr); }
  .podium { grid-template-columns: 1fr; }
  .field input { min-width: 0; width: 100%; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; }
}
